template <class K, class V> struct LruCache {
  std::size_t cap_; std::mutex m_;
  std::list<std::pair<K, V>> l_;                                 // MRU front
  std::unordered_map<K, decltype(l_)::iterator> idx_;            // key -> node
  std::optional<V> get(const K& k) {
    std::lock_guard g(m_);
    auto it = idx_.find(k);
    if (it == idx_.end()) return std::nullopt;
    l_.splice(l_.begin(), l_, it->second);                       // O(1) touch
    return it->second->second;
  } void put(K k, V v);   // insert front; at cap_ erase back() from both containers
};
